 public class ArkGame:MonoBehaviour {
  enum Page {Title,Home,Map,Entry,Story,Play,Result,Reward,Codex,Room,Settings}
  Page page;ArkBook book;AnimalCatalog catalog;ArkWorld world;ArkSound sound;ArkRun run;Font font;GUIStyle style;Texture2D atlas,cast;
  const string Key="archive.ark.v3";int owned,cleared,seen,stage,chapter,selected=-1,line,card,reward,roomMood;bool dev,after,replaying,opening,photo,first,autoCall;
  float scale,W,H,L,entered,lineAt,voiceAt,finishAt=-1;int[] newly=Array.Empty<int>();string notice="";ArkLine[] lines;
  List<Vector2> walk;int walking=-1,waypoint;bool boarding;Vector2 pointerDown;int dragging=-1;bool moved;float sparkleAt;Vector2 sparklePos;bool rolling;Vector3 ballTarget;
  Color ink=ArkWorld.Ink,paper=ArkWorld.Cream,gold=ArkWorld.Gold,red=ArkWorld.Terracotta;string[] chapters={"雨の庭","沈む記録","明日を乗せる舟"};string[] chapterMood={"小さな命に、最初の席を。","残すものは、重さでは決めない。","救われた声が、次の命を呼ぶ。"};
