  // V3 is preserved for rollback; VoyageGame owns the V4 runtime boot.
  static void Boot(){new GameObject("ArchiveGame").AddComponent<ArkGame>();}
  void Awake(){Application.targetFrameRate=30;Input.multiTouchEnabled=false;font=Resources.Load<Font>("Fonts/NotoSansJP");atlas=Resources.Load<Texture2D>("Art/animals-v2");cast=Resources.Load<Texture2D>("Art/cast-v3");book=JsonUtility.FromJson<ArkBook>(Resources.Load<TextAsset>("Data/ark").text);catalog=JsonUtility.FromJson<AnimalCatalog>(Resources.Load<TextAsset>("Data/animals").text);sound=gameObject.AddComponent<ArkSound>();world=gameObject.AddComponent<ArkWorld>();dev=Application.isEditor||Application.absoluteURL.Contains("dev=1");
   // Preserve the old collection, but start the newly written voyage independently.
   owned=PlayerPrefs.GetInt(Key+".owned",PlayerPrefs.GetInt("archive.v2.owned",0))&4095;cleared=PlayerPrefs.GetInt(Key+".clear",0)&511;seen=PlayerPrefs.GetInt(Key+".seen",0)&511;roomMood=PlayerPrefs.GetInt(Key+".light",0);Change(Page.Title);
  }
  bool Has(int id)=>(owned&(1<<id))!=0;bool Clear(int s)=>(cleared&(1<<s))!=0;bool Seen(int s)=>(seen&(1<<s))!=0;bool Open(int s)=>s==0||Clear(s-1);int Count(int n)=>Convert.ToString(n,2).Count(c=>c=='1');bool Busy=>Time.unscaledTime-entered<.3f;ArkStage Current=>book.stages[stage];
  void Save(){PlayerPrefs.SetInt(Key+".owned",owned);PlayerPrefs.SetInt(Key+".clear",cleared);PlayerPrefs.SetInt(Key+".seen",seen);PlayerPrefs.SetInt(Key+".light",roomMood);PlayerPrefs.Save();}
  void Change(Page p){page=p;rolling=false;entered=Time.unscaledTime;dragging=-1;photo=false;walking=-1;walk=null;autoCall=false;finishAt=-1;
   if(p==Page.Play){world.Build(chapter,Current);for(int i=0;i<Current.animals.Length;i++){var a=Current.animals[i];var c=world.Creature(a.id,run.positions[i],1.03f);c.root.gameObject.SetActive(!run.rescued[i]);}if(world.barrier)world.barrier.localPosition=run.opened?Vector3.down*1.5f:Vector3.zero;}
   else{int m=p==Page.Room?roomMood:p==Page.Story?chapter:p==Page.Map||p==Page.Entry?chapter:cleared==511?0:Mathf.Min(2,Count(cleared)/3);world.Build(m,null,p==Page.Room);if(p==Page.Reward)world.Creature(newly[reward],new Vector2(0,-.5f),2.5f);else if(p==Page.Story){world.Creature(Current.animals[0].id,new Vector2(-2,-.5f),1.6f);if(Current.animals.Length>1)world.Creature(Current.animals[1].id,new Vector2(2,1),1.1f);}else if(p==Page.Title){world.Creature(0,new Vector2(-1.7f,-2),1.5f);world.Creature(1,new Vector2(.3f,-.8f),1.4f);world.Creature(2,new Vector2(2.4f,1),1.2f);}else{var ids=Enumerable.Range(0,12).Where(Has).ToArray();foreach(int id in ids){float[] px={-2.8f,-.8f,1.7f,3.5f,-3,.6f,2.5f,3.3f,-3.4f,-.5f,1.2f,-.8f},pz={-2.2f,.8f,-1.6f,1.2f,1.7f,-2.9f,2.2f,-.4f,-.1f,2.6f,.3f,-.9f};float x=PlayerPrefs.GetFloat(Key+".pet"+id+"x",px[id]),z=PlayerPrefs.GetFloat(Key+".pet"+id+"z",pz[id]);var pet=world.Creature(id,new Vector2(x,z),p==Page.Room?1.12f:1.0f);pet.root.rotation=Quaternion.Euler(0,(id*47)%120-60,0);}if(ids.Length==0&&p==Page.Home)world.Creature(0,new Vector2(-.8f,-1),1.35f);} }
   if(p==Page.Room||p==Page.Home||p==Page.Title)world.Zoom=.89f;
   if(p==Page.Room){notice="動物も道具も、好きな場所へドラッグできます。";if(world.food)world.food.position=new Vector3(PlayerPrefs.GetFloat(Key+".foodx",-2.8f),.15f,PlayerPrefs.GetFloat(Key+".foodz",-2));if(world.toy)world.toy.position=new Vector3(PlayerPrefs.GetFloat(Key+".toyx",2.9f),.36f,PlayerPrefs.GetFloat(Key+".toyz",-1.5f));}
   int theme=p==Page.Story?chapter:p==Page.Play?chapter:p==Page.Room?(roomMood==2?1:3):p==Page.Reward||p==Page.Result?3:cleared==511?3:0;sound.Theme(theme);
  }
  void Begin(int s){stage=s;chapter=s/3;Change(Page.Entry);}
  void StartRescue(){run=new ArkRun(Current);selected=-1;notice=Current.brief;Change(Page.Play);}
  void Story(bool isAfter=false,bool replay=false,bool prologue=false){after=isAfter;replaying=replay;opening=prologue;lines=prologue?book.prologue:replay?Current.before.Concat(Current.after).ToArray():isAfter?Current.after:Current.before;line=0;lineAt=Time.unscaledTime;Change(Page.Story);sound.Theme(lines[0].mood=="tense"?Mathf.Max(1,chapter):lines[0].mood=="warm"?3:chapter);}
  void EndStory(){if(opening){PlayerPrefs.SetInt(Key+".intro",1);PlayerPrefs.Save();Change(Page.Home);}else if(replaying)Change(Page.Entry);else if(after)Change(Page.Map);else{seen|=1<<stage;Save();StartRescue();}}
  void Advance(){if(Time.unscaledTime-lineAt<lines[line].text.Length/29f){lineAt=Time.unscaledTime-lines[line].text.Length/29f-1;return;}if(++line>=lines.Length){EndStory();return;}lineAt=Time.unscaledTime;sound.Theme(lines[line].mood=="tense"?Mathf.Max(1,chapter):lines[line].mood=="warm"?3:chapter);}
  void Move(int a,Vector2 destination,bool exit){if(walking>=0||run==null||a<0||run.rescued[a])return;var path=run.Plan(a,destination);if(path==null){selected=a;notice=!run.opened?(Current.keeper>=0?"カメを選び、金色の鐘台へ。重さで門が開きます。":"道は水門の向こう。動物を選んで、金色の鐘台へ。"):"道がふさがっています。手前の仲間を先に動かそう。";sound.Play(6);world.DrawRoute(null);autoCall=false;return;}if(Vector2.Distance(path[0],destination)<.08f)return;walking=a;walk=path;waypoint=1;boarding=exit;selected=a;world.DrawRoute(path);notice="";sound.Play(1);}
  void FinishMove(){int a=walking;bool wasOpen=run.opened;if(!run.Commit(a,walk,boarding)){notice="道が変わりました。もう一度、行き先を選んでください。";world.animals[a].root.position=new Vector3(run.positions[a].x,.08f,run.positions[a].y);walking=-1;return;}walking=-1;world.DrawRoute(null);selected=-1;if(!wasOpen&&run.opened){notice="鐘が届いた。水門が開いて、道がつながった。";sound.Play(2);}if(boarding){world.animals[a].root.gameObject.SetActive(false);sound.Play(3);notice=catalog.animals[Current.animals[a].id].name+"、乗船。";}else if(!run.opened&&Current.keeper>=0&&Vector2.Distance(run.positions[a],new Vector2(Current.sx,Current.sz))<.7f)notice="まだ軽いみたい。カメのイシなら、動かせそう。";
   if(run.Remaining==0){autoCall=false;first=!Clear(stage);newly=Current.rewards.Where(id=>!Has(id)).ToArray();foreach(int id in newly)owned|=1<<id;cleared|=1<<stage;int best=PlayerPrefs.GetInt(Key+".best"+stage,999);if(run.moves<best)PlayerPrefs.SetInt(Key+".best"+stage,run.moves);Save();finishAt=Time.unscaledTime+.8f;}
  }
  void CallAll(){for(int i=0;i<run.positions.Length;i++)if(!run.rescued[i]&&run.Plan(i,Current.animals[i].Gate)!=null){Move(i,Current.animals[i].Gate,true);return;}autoCall=false;notice="先に鐘台で水門を開こう。";sound.Play(6);}
  void Update(){if(world==null)return;world.CameraStep(new Vector2(Input.mousePosition.x,Screen.height-Input.mousePosition.y));float now=Time.time;if(page==Page.Room&&rolling&&world.toy){world.toy.position=Vector3.MoveTowards(world.toy.position,ballTarget,Time.deltaTime*2);world.toy.Rotate(0,0,Time.deltaTime*220);if(Vector3.Distance(world.toy.position,ballTarget)<.03f){rolling=false;PlayerPrefs.SetFloat(Key+".toyx",ballTarget.x);PlayerPrefs.SetFloat(Key+".toyz",ballTarget.z);PlayerPrefs.Save();}}
   if(walking>=0){var c=world.animals[walking];var target=new Vector3(walk[waypoint].x,.08f,walk[waypoint].y);var direction=target-c.root.position;float speed=2.3f+Count(cleared)*.12f;c.root.position=Vector3.MoveTowards(c.root.position,target,Time.deltaTime*speed);if(direction.sqrMagnitude>.001f)c.root.rotation=Quaternion.Slerp(c.root.rotation,Quaternion.LookRotation(-direction.normalized),Time.deltaTime*12);if(Vector3.Distance(c.root.position,target)<.015f){waypoint++;if(waypoint>=walk.Count)FinishMove();}}
   if(page==Page.Play&&world.barrier)world.barrier.localPosition=Vector3.Lerp(world.barrier.localPosition,run.opened?Vector3.down*1.5f:Vector3.zero,Time.deltaTime*4);
   if(autoCall&&walking<0&&finishAt<0&&page==Page.Play)CallAll();
   for(int i=0;i<world.animals.Count;i++){var c=world.animals[i];bool moving=i==walking;if((page==Page.Room||page==Page.Home||page==Page.Title)&&dragging!=i){if(now>c.nextWander){c.nextWander=now+5+(c.id%4);float a=now*.7f+c.id*2;c.wander=new Vector2(Mathf.Cos(a)*3.3f,Mathf.Sin(a*.7f)*2.3f);}
     Vector3 to=new Vector3(c.wander.x,.08f,c.wander.y);Vector3 d=to-c.root.position;moving=d.magnitude>.08f;if(moving){Vector3 velocity=d.normalized*.48f;foreach(var other in world.animals){if(other==c)continue;Vector3 away=c.root.position-other.root.position;float distance=away.magnitude;if(distance<1.35f&&distance>.01f)velocity+=away.normalized*(1.35f-distance)*1.1f;}var proposed=c.root.position+Vector3.ClampMagnitude(velocity,.65f)*Time.deltaTime;proposed.x=Mathf.Clamp(proposed.x,-4.1f,4.1f);proposed.z=Mathf.Clamp(proposed.z,-3.6f,2.7f);if(!world.animals.Any(other=>other!=c&&Vector3.Distance(other.root.position,proposed)<.72f))c.root.position=proposed;else c.nextWander=Mathf.Min(c.nextWander,now+.6f);c.root.rotation=Quaternion.Slerp(c.root.rotation,Quaternion.LookRotation(-d.normalized),Time.deltaTime*2.5f);}}
    c.Pose(now,moving);
   }
   if(finishAt>0&&Time.unscaledTime>finishAt){Change(Page.Result);sound.Play(4);}
   if(page==Page.Story&&Time.unscaledTime-lineAt<lines[line].text.Length/29f&&Time.unscaledTime>voiceAt){bool nagi=lines[line].speaker=="ナギ";voiceAt=Time.unscaledTime+(nagi?.105f:.145f);sound.Play(nagi?5:7);}
   if(dev)Publish();
  }
  [Serializable]class DebugState {public string page;public int completed,owned,seen,level,selected,line,remaining,moves,walking,newRewards;public bool opened,muted;public float width,height,scale;public Vector2[] animals,gates;public Vector2 plate;public string positions;public int roomCount,roomActivities;public Vector2 food,toy;public string notice;public bool photo;}
  void Publish(){var s=new DebugState{page=page.ToString(),completed=cleared,owned=owned,seen=seen,level=stage,selected=selected,line=line,remaining=run==null?-1:run.Remaining,moves=run==null?0:run.moves,walking=walking,newRewards=newly.Length,opened=run!=null&&run.opened,muted=sound.Muted,width=W,height=H,scale=scale,roomCount=world.animals.Count};s.notice=notice;s.photo=photo;s.roomActivities=world.animals.Count(c=>Time.time<c.activityUntil);s.food=world.food?world.Screen(world.food.position):Vector2.zero;s.toy=world.toy?world.Screen(world.toy.position):Vector2.zero;s.animals=world.animals.Select(c=>world.Screen(c.root.position+Vector3.up*.6f)).ToArray();s.gates=Current.animals.Select(a=>world.Screen(new Vector3(a.gx,.2f,a.gz))).ToArray();s.plate=world.Screen(new Vector3(Current.sx,.2f,Current.sz));s.positions=run==null?"":string.Join(";",run.positions.Select((p,i)=>run.rescued[i]?"aboard":p.x.ToString("F2")+","+p.y.ToString("F2")));
   #if UNITY_WEBGL && !UNITY_EDITOR
   ArchiveState(JsonUtility.ToJson(s));
   #endif
  }
  public void DevCommand(string c){if(!dev)return;if(c.StartsWith("q")&&int.TryParse(c.Substring(1),out int n)&&n>=1&&n<=9){stage=n-1;chapter=stage/3;StartRescue();}if(c=="map")Change(Page.Map);if(c=="unlock"){cleared=511;owned=4095;seen=511;Save();Change(Page.Home);}if(c=="reset"){cleared=owned=seen=0;PlayerPrefs.DeleteKey(Key+".intro");Save();Change(Page.Title);}}
  void Box(Rect r,Color c){var old=GUI.color;GUI.color=c;GUI.DrawTexture(r,Texture2D.whiteTexture);GUI.color=old;}
  void Text(string t,Rect r,int size,Color color,TextAnchor align=TextAnchor.UpperLeft,bool bold=false){style.font=font;style.fontSize=size;style.normal.textColor=color;style.alignment=align;style.fontStyle=bold?FontStyle.Bold:FontStyle.Normal;style.wordWrap=true;GUI.Label(r,t,style);}
  bool Hit(Rect r,bool enabled=true){bool old=GUI.enabled;GUI.enabled=enabled&&!Busy;bool b=GUI.Button(r,GUIContent.none,GUIStyle.none);GUI.enabled=old;if(b)sound.Play(0);return b;}
  bool Button(string t,Rect r,bool primary=false,bool enabled=true){Box(r,enabled?(primary?red:new Color(ink.r,ink.g,ink.b,.94f)):new Color(ink.r,ink.g,ink.b,.52f));Box(new Rect(r.x,r.yMax-2,r.width,2),enabled?gold:new Color(.5f,.5f,.5f));Text(t,r,Mathf.Min(20,Mathf.Max(14,(int)((r.width-12)/Mathf.Max(1,t.Length)))),enabled?paper:new Color(.66f,.65f,.61f),TextAnchor.MiddleCenter);return Hit(r,enabled);}
  void Shade(float y,float height,float opacity){Box(new Rect(0,y,540,height),new Color(ink.r,ink.g,ink.b,opacity));}
  void Header(string small,string title,bool back=true){Shade(0,143,.90f);Text(small,new Rect(26,27,415,22),13,gold);Text(title,new Rect(24,62,440,55),29,paper,TextAnchor.UpperLeft,true);if(back&&Button("戻る",new Rect(438,26,78,54)))Change(Page.Home);}
  void OnGUI(){if(font==null)return;style=style??new GUIStyle();scale=Mathf.Min(Screen.width/540f,Screen.height/850f);W=Screen.width/scale;H=Screen.height/scale;L=(W-540)/2;GUI.matrix=Matrix4x4.Scale(new Vector3(scale,scale,1));
   GUI.BeginGroup(new Rect(L,0,540,H));switch(page){case Page.Title:Title();break;case Page.Home:Home();break;case Page.Map:Map();break;case Page.Entry:Entry();break;case Page.Story:Dialogue();break;case Page.Play:Play();break;case Page.Result:Result();break;case Page.Reward:Reward();break;case Page.Codex:Codex();break;case Page.Room:Room();break;case Page.Settings:Settings();break;}
   if(page==Page.Room||page==Page.Home||page==Page.Title)RoomInput();GUI.EndGroup();float fade=1-Mathf.Clamp01((Time.unscaledTime-entered)/.38f);if(fade>0)Box(new Rect(0,0,W,H),new Color(ink.r,ink.g,ink.b,fade));GUI.matrix=Matrix4x4.identity;
  }
  void Title(){Shade(0,255,.91f);Text("ANIMAL",new Rect(25,46,490,83),67,paper,TextAnchor.MiddleCenter,true);Text("A R C H I V E",new Rect(25,128,490,52),36,gold,TextAnchor.MiddleCenter);Text("明日を乗せる舟",new Rect(25,192,490,40),21,paper,TextAnchor.MiddleCenter);if(Button("旅をはじめる　→",new Rect(77,H-128,386,64),true)){if(PlayerPrefs.GetInt(Key+".intro",0)==0)Story(prologue:true);else Change(Page.Home);}Text("A SEAT FOR TOMORROW",new Rect(25,H-45,490,24),12,paper,TextAnchor.MiddleCenter);}
  void Home(){Header("THE ARK  /  HOME PORT","おかえり、守り手。",false);Box(new Rect(25,151,345,41),paper);Text(Count(owned)+"匹の仲間と、ひとつの舟。",new Rect(35,153,335,36),18,ink);int next=Enumerable.Range(0,9).FirstOrDefault(i=>!Clear(i));if(cleared==511)next=8;
   Shade(H-252,252,.91f);Text(cleared==511?"航海の記録は、いつでも読み返せます。":"NEXT  /  "+book.stages[next].title,new Rect(30,H-231,480,35),18,gold);if(Button(cleared==511?"航海の記録　→":"救助の旅へ　→",new Rect(26,H-181,488,62),true)){chapter=next/3;Change(Page.Map);}
   if(Button("仲間の庭",new Rect(26,H-99,153,58)))Change(Page.Room);if(Button("動物図鑑",new Rect(193,H-99,153,58)))Change(Page.Codex);if(Button("音と設定",new Rect(360,H-99,154,58)))Change(Page.Settings);
