  void Map(){Header("VOYAGE  /  "+(chapter+1).ToString("00"),chapters[chapter]);Shade(143,H-143,.35f);for(int i=0;i<3;i++){int c=i;if(Button(new[]{"雨の庭","沈む記録","嵐の門"}[i],new Rect(26+i*165,161,155,52),chapter==i)){chapter=c;Change(Page.Map);}}
   Text(chapterMood[chapter],new Rect(30,238,480,58),21,paper);float start=Mathf.Max(325,H*.39f);for(int i=0;i<3;i++){int s=chapter*3+i;float y=start+i*111;Box(new Rect(28,y,484,92),new Color(ink.r,ink.g,ink.b,.94f));Box(new Rect(28,y,5,92),Clear(s)?gold:Open(s)?red:new Color(.4f,.4f,.43f));Text((s+1).ToString("00"),new Rect(44,y+19,60,50),33,Open(s)?gold:new Color(.5f,.5f,.5f));Text(book.stages[s].title,new Rect(121,y+12,368,40),24,paper);Text(Clear(s)?"乗船済  /  物語・再挑戦":Open(s)?"新しい足音　→":"前の救助を終えると開放",new Rect(122,y+55,370,29),16,Open(s)?gold:paper);if(Hit(new Rect(28,y,484,92),Open(s)))Begin(s);}
   Text("救助 "+Count(cleared)+" / 9　　仲間 "+Count(owned)+" / 12",new Rect(25,H-66,490,32),17,paper,TextAnchor.MiddleCenter);
  }
  void Entry(){Header(Current.place,Current.title);Shade(H-315,315,.96f);Text(Current.brief,new Rect(30,H-290,480,75),22,paper);if(Seen(stage)){if(Button("物語を読み返す",new Rect(28,H-192,484,60))){Story(replay:true);}if(Button("救助を始める　→",new Rect(28,H-114,484,62),true))StartRescue();}else{Text("物語から救助へ、そのまま進みます。",new Rect(30,H-193,480,34),17,gold);if(Button("物語から進む　→",new Rect(28,H-126,484,66),true))Story();}if(Button("航路に戻る",new Rect(28,158,164,49)))Change(Page.Map);}
  void Portrait(bool man,Rect r,float alpha){int expression=lines[line].mood=="tense"?1:lines[line].mood=="warm"?2:0;var old=GUI.color;GUI.color=new Color(1,1,1,alpha);GUI.DrawTextureWithTexCoords(r,cast,new Rect(expression/3f,man?0:.5f,1/3f,.5f));GUI.color=old;}
  void Dialogue(){var l=lines[line];Shade(0,105,.86f);Text(opening?"PROLOGUE  /  雨の音":Current.place,new Rect(26,24,385,24),14,gold);Text(opening?"名前を呼ぶ人":Current.title,new Rect(26,56,385,36),24,paper);if(Button("省略",new Rect(434,26,80,52)))EndStory();
   float bottom=H-248;bool nagi=l.speaker=="ナギ";float bob=Mathf.Sin(Time.time*1.3f)*2;Portrait(!nagi,new Rect(nagi?165:-5,bottom-375+bob,380,380),1);
   if(l.mood=="tense"){Box(new Rect(0,105,4,bottom-105),red);Text("雨音が、近づく。",new Rect(28,bottom-106,205,50),17,ink);}else if(l.mood=="warm")Text("小さな足音が、そばに。",new Rect(nagi?28:294,bottom-106,218,55),17,ink);
   Shade(bottom,248,.97f);Box(new Rect(28,bottom+24,4,30),nagi?gold:red);Text(l.speaker,new Rect(47,bottom+20,440,39),23,gold);int n=Mathf.Clamp((int)((Time.unscaledTime-lineAt)*29),0,l.text.Length);Text(l.text.Substring(0,n),new Rect(28,bottom+74,484,124),23,paper);Text(n<l.text.Length?"タップで全文":"画面をタップして次へ　›",new Rect(130,H-41,384,29),14,gold,TextAnchor.MiddleRight);
   var e=Event.current;if(!Busy&&e.type==EventType.MouseUp&&e.button==0){Advance();e.Use();}
