  Vector2 Local(Vector3 worldPoint){Vector2 v=world.Screen(worldPoint)/scale;v.x-=L;return v;}
  Vector2 Pixels(Vector2 local)=>new Vector2((local.x+L)*scale,local.y*scale);
  void Play(){Header(Current.place,Current.title,false);Box(new Rect(24,148,145,40),paper);Box(new Rect(345,148,171,40),paper);Text("あと "+run.Remaining+"匹",new Rect(28,149,220,32),20,ink,TextAnchor.MiddleLeft,true);Text(run.moves+" 回の合図",new Rect(280,149,232,32),18,ink,TextAnchor.MiddleRight);
   for(int i=0;i<Current.animals.Length;i++){if(run.rescued[i])continue;var a=Current.animals[i];var p=Local(new Vector3(a.gx,.3f,a.gz));Rect r=new Rect(p.x-47,p.y-42,94,53);Box(r,selected==i?red:new Color(ink.r,ink.g,ink.b,.94f));Animal(a.id,new Rect(r.x+4,r.y+2,38,42));Text(a.id==4?"博士":catalog.animals[a.id].name,new Rect(r.x+42,r.y+3,51,46),12,paper,TextAnchor.MiddleCenter);if(Hit(r,walking<0&&finishAt<0))Move(i,a.Gate,true);}
   if(Current.lever&&!run.opened){var p=Local(new Vector3(Current.sx,.2f,Current.sz));var r=new Rect(p.x-37,p.y-36,74,42);Box(r,gold);Text("鐘台",r,17,ink,TextAnchor.MiddleCenter,true);if(Hit(r,walking<0)){if(selected>=0)Move(selected,new Vector2(Current.sx,Current.sz),false);else{notice="動物を選んでから、鐘台をタップ。";sound.Play(6);}}}
