  int ClosestAnimal(Vector2 p){float d=52;int found=-1;for(int i=0;i<world.animals.Count;i++){var c=world.animals[i];if(!c.root.gameObject.activeSelf)continue;var q=Local(c.root.position+Vector3.up*.57f);float n=Vector2.Distance(p,q);if(n<d){d=n;found=i;}}return found;}
  void Result(){Header("RESCUE COMPLETE",Current.title,false);Shade(H-307,307,.97f);Text("みんな、乗れた。",new Rect(28,H-282,484,58),35,paper,TextAnchor.MiddleCenter,true);Text(run.moves+"回の合図  /  最少 "+PlayerPrefs.GetInt(Key+".best"+stage)+"回",new Rect(28,H-211,484,36),18,gold,TextAnchor.MiddleCenter);Text(newly.Length>0?newly.Length+"匹の新しい仲間が、方舟で待っています。":"新しい仲間の登録はありません。",new Rect(28,H-161,484,37),18,paper,TextAnchor.MiddleCenter);if(Button(newly.Length>0?"仲間に会う　→":first?"つづきを読む　→":"航路へ戻る　→",new Rect(42,H-102,456,62),true)){if(newly.Length>0){reward=0;Change(Page.Reward);}else if(first)Story(true);else Change(Page.Map);}}
