  void Animal(int id,Rect dest,float alpha=1){Rect s=sources[id];float fit=Mathf.Min(dest.width/s.width,dest.height/s.height);Rect r=new Rect(dest.center.x-s.width*fit/2,dest.center.y-s.height*fit/2,s.width*fit,s.height*fit);var old=GUI.color;GUI.color=new Color(1,1,1,alpha);GUI.DrawTextureWithTexCoords(r,atlas,new Rect(s.x/atlas.width,1-(s.y+s.height)/atlas.height,s.width/atlas.width,s.height/atlas.height));GUI.color=old;}
  void Codex(){Header("PASSENGERS  /  "+Count(owned)+" OF 12","小さな命の名簿");Shade(143,H-143,.82f);float top=168,rh=Mathf.Min(143,(H-447)/3);for(int i=0;i<12;i++){Rect r=new Rect(24+(i%4)*125,top+(i/4)*rh,116,rh-10);Box(r,Has(i)?paper:ink);Animal(i,new Rect(r.x+8,r.y+3,r.width-16,r.height-32),Has(i)?1:.16f);Text(Has(i)?catalog.animals[i].name:"まだ会わない",new Rect(r.x+2,r.yMax-28,r.width-4,25),13,Has(i)?ink:paper,TextAnchor.MiddleCenter);if(i==card)Box(new Rect(r.x,r.yMax-3,r.width,3),red);if(Hit(r))card=i;}float y=top+rh*3+13;Text(Has(card)?catalog.animals[card].species+" / "+catalog.animals[card].name:"まだ知らない、小さな足音",new Rect(28,y,484,47),27,gold);Text(Has(card)?AnimalMemory(card):"航海を進めると、この席にも名前が増えます。",new Rect(28,y+60,484,82),22,paper);if(Button("仲間の庭へ　→",new Rect(28,H-91,484,60),true))Change(Page.Room);}
