  void RoomInput(){var e=Event.current;if(e.type==EventType.ScrollWheel){world.CameraStep(Pixels(e.mousePosition),e.delta.y);e.Use();return;}if(page!=Page.Room)return;if(photo){if(e.type==EventType.MouseUp&&!Busy){photo=false;e.Use();}return;}if(e.type==EventType.MouseDown&&!Busy&&e.mousePosition.y>205&&e.mousePosition.y<H-129){pointerDown=e.mousePosition;moved=false;if(Vector2.Distance(e.mousePosition,Local(world.food.position))<28)dragging=100;else if(Vector2.Distance(e.mousePosition,Local(world.toy.position))<28)dragging=101;else dragging=ClosestAnimal(e.mousePosition);if(dragging>=0)e.Use();}
   if(dragging>=0&&(e.type==EventType.MouseDrag||e.type==EventType.MouseUp)){if(Vector2.Distance(e.mousePosition,pointerDown)>9)moved=true;var p=world.Ground(Pixels(e.mousePosition));p.x=Mathf.Clamp(p.x,-4.1f,4.1f);p.y=Mathf.Clamp(p.y,-3.8f,2.6f);Transform t=dragging==100?world.food:dragging==101?world.toy:world.animals[dragging].root;if(moved)t.position=new Vector3(p.x,t.position.y,p.y);
    if(e.type==EventType.MouseUp){if(dragging<100){var c=world.animals[dragging];c.wander=new Vector2(t.position.x,t.position.z);c.nextWander=Time.time+9;c.happyUntil=Time.time+1.2f;PlayerPrefs.SetFloat(Key+".pet"+c.id+"x",t.position.x);PlayerPrefs.SetFloat(Key+".pet"+c.id+"z",t.position.z);notice=catalog.animals[c.id].name+(moved?"の居場所を動かしました。":"が、うれしそうに寄り添った。");sparklePos=Local(t.position);sparkleAt=Time.unscaledTime;sound.Play(8);}else{string item=dragging==100?"food":"toy";PlayerPrefs.SetFloat(Key+"."+item+"x",t.position.x);PlayerPrefs.SetFloat(Key+"."+item+"z",t.position.z);if(!moved){if(dragging==101){ballTarget=new Vector3(-t.position.x*.65f,.36f,Mathf.Clamp(t.position.z+1.2f,-3,2));rolling=true;}Vector3 activityPoint=dragging==101?ballTarget:t.position;int n=0;foreach(var c in world.animals.OrderBy(c=>Vector3.Distance(c.root.position,t.position)).Take(4)){float a=n++*Mathf.PI/2;c.wander=new Vector2(activityPoint.x+Mathf.Cos(a)*.8f,activityPoint.z+Mathf.Sin(a)*.8f);c.nextWander=Time.time+18;c.activity=dragging==100?1:2;c.activityUntil=Time.time+18;}notice=dragging==100?"ごはんの音に、小さな足音が集まってくる。":"ボールを追いかけて、庭がにぎやかになった。";sound.Play(2);}}PlayerPrefs.Save();dragging=-1;}e.Use();}
